        "Sydney", "NSW",
        "Melbourne", "VIC",
        "Brisbane", "QLD");

    private Locality() {
    }

    /**
     * Derives the region for an owner, preferring the postcode range and falling back to
     * the city-to-region table. Returns {@link #UNKNOWN} for a {@code null} owner or when
     * neither route resolves a region.
